    "noImplicitOverride": true,
    "noFallthroughCasesInSwitch": true
  }
}

import type { User } from "./types.js";
import { type Order, createOrder } from "./orders.js";

export type { User };   // type-only re-export, safe under isolatedModules

// types/env.d.ts
declare const __APP_VERSION__: string;

declare module "*.svg" {
  const src: string;
  export default src;
}

// augment Express
import "express";
declare module "express-serve-static-core" {
  interface Request { userId?: string }
}

type IsString<T> = T extends string ? true : false;
type A = IsString<"hi">;   // true
type B = IsString<42>;     // false

type MyExclude<T, U> = T extends U ? never : T;
type C = MyExclude<"a" | "b" | "c", "a">;  // "b" | "c"

type ToArray<T> = T extends unknown ? T[] : never;
type D = ToArray<string | number>;      // string[] | number[]

type ToArrayND<T> = [T] extends [unknown] ? T[] : never;
type E = ToArrayND<string | number>;    // (string | number)[]

type IsNeverWrong<T> = T extends never ? true : false;
type F = IsNeverWrong<never>;           // never (distributes over empty union)
type IsNever<T> = [T] extends [never] ? true : false;
type G = IsNever<never>;                // true

type MyReturnType<F> = F extends (...args: any[]) => infer R ? R : never;
type UnwrapPromise<T> = T extends Promise<infer V> ? V : T;
type ElementOf<T> = T extends readonly (infer E)[] ? E : never;
type First<T extends unknown[]> = T extends [infer H, ...unknown[]] ? H : never;

type P = UnwrapPromise<Promise<string>>;  // string
type Q = First<[1, 2, 3]>;                // 1

type ToNum<S> = S extends `${infer N extends number}` ? N : never;
type R = ToNum<"42">;                     // 42

type Flatten<T> = T extends readonly (infer E)[] ? Flatten<E> : T;
type H = Flatten<number[][][]>;   // number

type DeepAwaited<T> = T extends PromiseLike<infer V> ? DeepAwaited<V> : T;

type Reverse<T extends unknown[]> =
  T extends [infer Head, ...infer Tail] ? [...Reverse<Tail>, Head] : [];
type I = Reverse<[1, 2, 3]>;      // [3, 2, 1]

type Equal<A, B> =
  (<T>() => T extends A ? 1 : 2) extends (<T>() => T extends B ? 1 : 2) ? true : false;
type Expect<T extends true> = T;

type test1 = Expect<Equal<MyReturnType<() => string>, string>>;

// Vitest
// expectTypeOf(parse("1")).toEqualTypeOf<number>();

type MyPartial<T> = { [K in keyof T]?: T[K] };
type MyReadonly<T> = { readonly [K in keyof T]: T[K] };
type MyPick<T, K extends keyof T> = { [P in K]: T[P] };
type MyRecord<K extends PropertyKey, V> = { [P in K]: V };

type Flags = { [K in "dark" | "compact"]: boolean };  // { dark: boolean; compact: boolean }

type MyRequired<T> = { [K in keyof T]-?: T[K] };
type Mutable<T> = { -readonly [K in keyof T]: T[K] };

type DeepReadonly<T> = T extends (...args: any[]) => any
  ? T
  : T extends object
    ? { readonly [K in keyof T]: DeepReadonly<T[K]> }
    : T;

type Getters<T> = {
  [K in keyof T as `get${Capitalize<string & K>}`]: () => T[K];
};
type G = Getters<{ name: string; age: number }>;
// { getName: () => string; getAge: () => number }

type PickByValue<T, V> = { [K in keyof T as T[K] extends V ? K : never]: T[K] };
type Strs = PickByValue<{ a: string; b: number; c: string }, string>;  // { a: string; c: string }

type Size = "sm" | "lg";
type Color = "red" | "blue";
type ClassName = `${Size}-${Color}`;   // "sm-red" | "sm-blue" | "lg-red" | "lg-blue"

type Px = `${number}px`;
const w: Px = "12px";   // OK
// const h: Px = "12";  // Error

type Params<S> = S extends `${string}:${infer P}/${infer Rest}`
  ? P | Params<Rest>
  : S extends `${string}:${infer P}` ? P : never;
type R = Params<"/users/:id/posts/:postId">;  // "id" | "postId"

type Paths<T> = T extends object
  ? {
      [K in keyof T & string]: T[K] extends object
        ? K | `${K}.${Paths<T[K]>}`
        : K;
    }[keyof T & string]
  : never;

type Form = { user: { name: string; address: { city: string } }; agree: boolean };
type P = Paths<Form>;
// "user" | "user.name" | "user.address" | "user.address.city" | "agree"

type Route = { path: string; auth?: boolean };

const routes = {
  home: { path: "/" },
  admin: { path: "/admin", auth: true },
} satisfies Record<string, Route>;

routes.admin.path;      // OK, and keys are known: "home" | "admin"
// routes.missing;      // Error: property does not exist

const routes2: Record<string, Route> = { home: { path: "/" } };
routes2.missing;        // No error: type is Record<string, Route>

const palette = {
  primary: "#3b82f6",
  danger: "#ef4444",
} as const satisfies Record<string, `#${string}`>;

type PaletteKey = keyof typeof palette;   // "primary" | "danger"
// palette.primary is the literal "#3b82f6" and readonly

declare const brand: unique symbol;
type Brand<T, B extends string> = T & { readonly [brand]: B };

type UserId = Brand<string, "UserId">;
type OrderId = Brand<string, "OrderId">;

function toUserId(s: string): UserId {
  if (!/^u_/.test(s)) throw new Error("bad id");
  return s as UserId;
}

declare function getUser(id: UserId): void;
// getUser("u_1");                 // Error: string is not UserId
getUser(toUserId("u_1"));          // OK

interface Animal { name: string }
interface Dog extends Animal { bark(): void }

let handleAnimal = (a: Animal) => {};
let handleDog = (d: Dog) => d.bark();

handleDog = handleAnimal;   // OK: Animal handler accepts any Dog
// handleAnimal = handleDog; // Error under strictFunctionTypes

const dogs: Dog[] = [];
const animals: Animal[] = dogs;   // allowed: arrays are treated covariantly (unsound)
animals.push({ name: "cat" });    // now dogs contains a non-dog

